private func key_button(at point: CGPoint) -> KeyButton? {
    for row in self.rows {
        for button in row {
            if self.point(point, inside: button) {
                return button
            }
        }
    }

    var best_button: KeyButton?
    var best_distance = CGFloat.greatestFiniteMagnitude
    for row in self.rows {
        for button in row {
            let frame = button.hit_frame ?? button.frame
            guard !frame.isEmpty else {
                continue
            }

            let dx = max(max(frame.minX - point.x, 0), point.x - frame.maxX)
            let dy = max(max(frame.minY - point.y, 0), point.y - frame.maxY)
            let distance = dx * dx + dy * dy
            if distance < best_distance {
                best_distance = distance
                best_button = button
            }
        }
    }

    return best_button
}

private func point(_ point: CGPoint, inside button: KeyButton) -> Bool {
    let frame = button.hit_frame ?? button.frame
    return frame.contains(point)
